import random


def strategy(history, rng):
    if not history:
        return 'C'

    n = len(history)
    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    # Defect near the end, but keep some cooperation early.
    # In the last few rounds, exploit if opponent seems cooperative.
    if n >= 96:
        coop_rate = sum(1 for x in opp if x == 'C') / float(n)
        if coop_rate > 0.55:
            return 'D'
        return 'C'

    # Detect always-defect quickly and switch to defection.
    if n >= 4:
        recent_opp = opp[-4:]
        if all(x == 'D' for x in recent_opp):
            return 'D'

    # Retaliate immediately after defection, then forgive after one punishment round.
    if opp[-1] == 'D':
        # If opponent has defected more than once in the last 3, stay defensive.
        if n >= 3 and opp[-3:].count('D') >= 2:
            return 'D'
        return 'D'

    # If we just defected as punishment, return to cooperation.
    if me[-1] == 'D' and opp[-1] == 'C':
        return 'C'

    # Default: cooperate, but occasionally probe late to test exploitation opportunities.
    if n >= 80 and n < 96 and n % 7 == 0:
        if rng.random() < 0.25:
            return 'D'
    return 'C'
